const e="mit-adt-quasar-cultural-competitions",d=2025,n="Read from the Quasar 2025 cultural competitions guidelines (30 October 2025). Not printed: ages, years of study, entry fee, venue, contact people, prize amounts and the registration link as text (only a scan code). The heading 'SwarFusion 2025 - Singing Competition' is read as the instrumental competition because its categories are solo and duet instrumental. The document says 'all colleges' for three competitions and 'all Design colleges' for two; both are recorded. 'Co-ordinated by' is printed as a logo only.",t={Title:"Rules & Criteria",Subtitle:"MIT-ADT University Quasar 2025 - cultural competitions",NoticeTitle:"Please Read Before Registering",Notice:"Competitions run on {{SingingDate}} to {{DanceDate}}. Music and video files are due by {{MusicDeadline}}. Report to the coordinator at least 1 hour before your slot.",Notes:["Each college may send at most 2 entries per competition (2 groups for the group dance).","The judges' decision is final.","The number of prizes is decided according to the number of entries."],Sections:[{Key:"general",Title:"General",Items:["The cultural competitions are Aalaap (singing), SwarFusion (instrumental), Abhivyakti (solo act), Mic Drop (stand-up comedy) and NrityaVerse (dance).","The judges' decision is final.","The number of prizes is decided according to the number of entries. Cash prizes are offered.","Plagiarism leads to disqualification. This means copying another participant's arrangement (singing), pre-recorded audio (instrumental), copying scripts or performance material (solo act), plagiarism or offensive content (stand-up) and copying another group's choreography (dance).","Late submissions and late entries are not accepted. Late arrivals may be disqualified in Mic Drop.","Stage decorum must be maintained at all times. Vulgar, offensive or inappropriate content leads to disqualification."]},{Key:"eligibility",Title:"Who may enter",Items:["Aalaap, SwarFusion and Abhivyakti are open to students from all colleges.","Mic Drop and NrityaVerse are open to students from all Design colleges.","Each college can send a maximum of 2 entries (singing, instrumental solo or duet), 2 participants (solo act, stand-up comedy) or 2 groups (dance).","Singing and solo act: only one entry per participant.","Singing: only individual performances (no duets or groups).","Instrumental: only solo or duet performances are allowed (no large groups).","Solo act: only solo performances (no duets or group acts).","Stand-up comedy: only solo performances.","Dance: every group must have at least 4 members and not more than 12."]},{Key:"registration",Title:"How to enter",Items:["Register by scanning the registration code printed on the guidelines. {{RegistrationCode}}","Singing and dance: submit the final music track and background visuals as a single video file by {{MusicDeadline}}. Once submitted, no changes are allowed for any reason.","On the day, participants report to the coordinator at least 1 hour before the competition begins (the whole group for dance).","Late submissions will not be accepted."]},{Key:"dates",Title:"Dates and times",Items:["Aalaap (singing): {{SingingDate}} at {{SingingTime}}.","SwarFusion (instrumental): {{InstrumentalDate}} at {{InstrumentalTime}}.","Abhivyakti (solo act): {{SoloActDate}} at {{SoloActTime}}.","Mic Drop (stand-up comedy): {{StandUpDate}} at {{StandUpTime}}.","NrityaVerse (dance): {{DanceDate}} at {{DanceTime}}.","Music and video file deadline for singing and dance: {{MusicDeadline}}."]},{Key:"judging",Title:"Judging",Items:["The judges' decision is final.","Criteria are printed as percentages for each competition; they are listed with each competition."]},{Key:"prizes",Title:"Prizes",Items:["Cash prizes are offered. {{Prizes}}","The number of prizes is decided according to the number of entries."]}],Documents:[{Title:"Guidelines and Rules for all cultural competitions, Quasar 2025 (PDF)",Url:"https://mitid.edu.in/quasar/pdf/cultural-competitions-30oct2025.pdf"}]},i=[{ParticipantType:"Team",Source:"Dance and instrumental duet rules",Sections:{About:null,TimeAndFormat:null,Rules:["Instrumental duets have 2 performers.","Dance groups have at least 4 and at most 12 members, and each college can send at most 2 groups."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Instrumental duets have 2 performers.
- Dance groups have at least 4 and at most 12 members, and each college can send at most 2 groups.`}],a=[],o=JSON.parse(`[{"Title":"Solo Singing","Source":"1. Aalaap 2025","Sections":{"About":["Aalaap 2025 - Singing Competition, 'Design Your Voice, Define Your Stage'. Solo singing performance."],"TimeAndFormat":["Strict 3-minute time limit; exceeding it leads to disqualification.","The submitted file is MP4 (preferred), at most 3 minutes."],"Rules":["Participants bring their own background music track (instrumental or karaoke version).","Background visuals are optional but encouraged.","The music track and background video are exported as a single video file before submission.","Submit the final file by {{MusicDeadline}}; no changes after that.","File naming: CollegeName_ParticipantName_SongTitle.mp4.","Video and audio quality must be clear and distortion-free.","Participants perform live along with the pre-submitted background video or music.","Report to the coordinator at least 1 hour before the competition begins."],"Allowed":null,"NotAllowed":null,"Judging":["Vocal quality and pitch control 60%, creativity and originality 20%, stage presence and confidence 20%."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Aalaap 2025 - Singing Competition, 'Design Your Voice, Define Your Stage'. Solo singing performance.\\n\\n## Time and format\\n- Strict 3-minute time limit; exceeding it leads to disqualification.\\n- The submitted file is MP4 (preferred), at most 3 minutes.\\n\\n## Rules\\n- Participants bring their own background music track (instrumental or karaoke version).\\n- Background visuals are optional but encouraged.\\n- The music track and background video are exported as a single video file before submission.\\n- Submit the final file by {{MusicDeadline}}; no changes after that.\\n- File naming: CollegeName_ParticipantName_SongTitle.mp4.\\n- Video and audio quality must be clear and distortion-free.\\n- Participants perform live along with the pre-submitted background video or music.\\n- Report to the coordinator at least 1 hour before the competition begins.\\n\\n## Judging\\n- Vocal quality and pitch control 60%, creativity and originality 20%, stage presence and confidence 20%."},{"Title":"Solo Instrumental","Source":"2. SwarFusion 2025","Sections":{"About":["SwarFusion 2025 - 'Where tradition meets innovation'. Solo instrumental performance."],"TimeAndFormat":["Maximum performance duration: 4 minutes. Exceeding the limit may lead to disqualification."],"Rules":["Participants bring and play their own instruments.","The organisers provide a basic stage set-up (1-2 microphones, 2 inputs for guitar); participants are responsible for any other instrument-specific needs.","A brief sound check is given before the slot.","Instruments must be safe and non-disruptive."],"Allowed":null,"NotAllowed":["Pre-recorded tracks or background music: only live performance. Fire, smoke or hazardous items."],"Judging":["Musical skill and technique 40%, creativity and originality 25%, stage presence and expression 20%, coordination (for duets) 15%. The criteria for a solo performance are not given separately."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- SwarFusion 2025 - 'Where tradition meets innovation'. Solo instrumental performance.\\n\\n## Time and format\\n- Maximum performance duration: 4 minutes. Exceeding the limit may lead to disqualification.\\n\\n## Rules\\n- Participants bring and play their own instruments.\\n- The organisers provide a basic stage set-up (1-2 microphones, 2 inputs for guitar); participants are responsible for any other instrument-specific needs.\\n- A brief sound check is given before the slot.\\n- Instruments must be safe and non-disruptive.\\n\\n## Not allowed\\n- Pre-recorded tracks or background music: only live performance. Fire, smoke or hazardous items.\\n\\n## Judging\\n- Musical skill and technique 40%, creativity and originality 25%, stage presence and expression 20%, coordination (for duets) 15%. The criteria for a solo performance are not given separately."},{"Title":"Duet Instrumental","Source":"2. SwarFusion 2025","Sections":{"About":["SwarFusion 2025 - duet instrumental performance."],"TimeAndFormat":["Maximum performance duration: 4 minutes."],"Rules":["Both players bring and play their own instruments; only live performance is allowed.","A college can send a maximum of 2 entries (solo or duet)."],"Allowed":null,"NotAllowed":null,"Judging":["Musical skill and technique 40%, creativity and originality 25%, stage presence and expression 20%, coordination 15%."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- SwarFusion 2025 - duet instrumental performance.\\n\\n## Time and format\\n- Maximum performance duration: 4 minutes.\\n\\n## Rules\\n- Both players bring and play their own instruments; only live performance is allowed.\\n- A college can send a maximum of 2 entries (solo or duet).\\n\\n## Judging\\n- Musical skill and technique 40%, creativity and originality 25%, stage presence and expression 20%, coordination 15%."},{"Title":"Solo Act","Source":"3. Abhivyakti 2025","Sections":{"About":["Abhivyakti 2025 - Solo Act Competition, 'One stage. One performer. Infinite stories.' Theatre, monologue, performance art or spoken word that tells the story of a character."],"TimeAndFormat":["Maximum performance duration: 4 minutes; strict adherence is mandatory.","2 minutes are given for stage set-up, not counted in the performance."],"Rules":["Language of performance: Hindi or English.","Props, minimal sets and hand-held items are free to use.","Report to the coordinator at least 1 hour before the scheduled slot.","Respect for fellow performers and proper decorum are required."],"Allowed":null,"NotAllowed":["Vulgar, offensive or inappropriate content (disqualification).","Copying scripts or performance material."],"Judging":["Creativity and originality of performance 35%, acting, emotional range and expression 30%, stage presence and confidence 20%, effective use of props and audio (if any) 15%."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Abhivyakti 2025 - Solo Act Competition, 'One stage. One performer. Infinite stories.' Theatre, monologue, performance art or spoken word that tells the story of a character.\\n\\n## Time and format\\n- Maximum performance duration: 4 minutes; strict adherence is mandatory.\\n- 2 minutes are given for stage set-up, not counted in the performance.\\n\\n## Rules\\n- Language of performance: Hindi or English.\\n- Props, minimal sets and hand-held items are free to use.\\n- Report to the coordinator at least 1 hour before the scheduled slot.\\n- Respect for fellow performers and proper decorum are required.\\n\\n## Not allowed\\n- Vulgar, offensive or inappropriate content (disqualification).\\n- Copying scripts or performance material.\\n\\n## Judging\\n- Creativity and originality of performance 35%, acting, emotional range and expression 30%, stage presence and confidence 20%, effective use of props and audio (if any) 15%."},{"Title":"Stand-Up Comedy","Source":"4. Mic Drop 2025","Sections":{"About":["Mic Drop 2025 - Stand Up Comedy Competition, 'One mic. One stool. Infinite laughter.' Solo stand-up comedy performance."],"TimeAndFormat":["Maximum performance duration: 4 minutes; strict adherence is mandatory."],"Rules":["Each performer gets one stool and one microphone on stage.","Minimal hand-held props may be brought.","Performers come fully prepared with their script and jokes, and report to the coordinator at least 1 hour before their slot."],"Allowed":null,"NotAllowed":["Pre-recorded audio or music, external devices and live audio tracks.","Vulgarity, offensive content or hate speech."],"Judging":["Humor and originality 40%, timing and delivery 30%, audience engagement and confidence 20%, stage presence and creativity 10%."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Mic Drop 2025 - Stand Up Comedy Competition, 'One mic. One stool. Infinite laughter.' Solo stand-up comedy performance.\\n\\n## Time and format\\n- Maximum performance duration: 4 minutes; strict adherence is mandatory.\\n\\n## Rules\\n- Each performer gets one stool and one microphone on stage.\\n- Minimal hand-held props may be brought.\\n- Performers come fully prepared with their script and jokes, and report to the coordinator at least 1 hour before their slot.\\n\\n## Not allowed\\n- Pre-recorded audio or music, external devices and live audio tracks.\\n- Vulgarity, offensive content or hate speech.\\n\\n## Judging\\n- Humor and originality 40%, timing and delivery 30%, audience engagement and confidence 20%, stage presence and creativity 10%."},{"Title":"Group Dance","Source":"5. NrityaVerse 2025","Sections":{"About":["NrityaVerse 2025 - Dance Competition, 'Where classical roots meet contemporary moves'. Group dance of 4 to 12 participants."],"TimeAndFormat":["Maximum duration 5 minutes per performance; strict adherence is mandatory.","Groups get 2 minutes for stage set-up and clearance.","The submitted file is MP4, at most 5 minutes."],"Rules":["Theme: Fusion - blending classical, folk or traditional dance forms with contemporary or modern styles. Creativity in choreography and music choice is encouraged.","Submit the final music track and background visuals as a single video file by {{MusicDeadline}}. The file is played during the performance; no live musicians or last-minute changes.","Music once submitted cannot be changed for any reason.","File naming: CollegeName_GroupName_DanceTitle.mp4. Audio and video must be clear and distortion-free.","Groups arrange their own costumes, props and choreography.","All group members report to the coordinator at least 1 hour before the competition begins.","Each college can send a maximum of 2 groups, of 4 to 12 members each.","Proper stage decorum must be kept before, during and after the performance."],"Allowed":null,"NotAllowed":["Fire, water or any hazardous props.","Vulgarity, offensive gestures or inappropriate content.","External devices on stage: only the submitted track or video is allowed."],"Judging":["Choreography and creativity (Fusion theme) 40%, synchronization and coordination 25%, stage presence and expression 20%, costume, energy and overall impact 15%."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- NrityaVerse 2025 - Dance Competition, 'Where classical roots meet contemporary moves'. Group dance of 4 to 12 participants.\\n\\n## Time and format\\n- Maximum duration 5 minutes per performance; strict adherence is mandatory.\\n- Groups get 2 minutes for stage set-up and clearance.\\n- The submitted file is MP4, at most 5 minutes.\\n\\n## Rules\\n- Theme: Fusion - blending classical, folk or traditional dance forms with contemporary or modern styles. Creativity in choreography and music choice is encouraged.\\n- Submit the final music track and background visuals as a single video file by {{MusicDeadline}}. The file is played during the performance; no live musicians or last-minute changes.\\n- Music once submitted cannot be changed for any reason.\\n- File naming: CollegeName_GroupName_DanceTitle.mp4. Audio and video must be clear and distortion-free.\\n- Groups arrange their own costumes, props and choreography.\\n- All group members report to the coordinator at least 1 hour before the competition begins.\\n- Each college can send a maximum of 2 groups, of 4 to 12 members each.\\n- Proper stage decorum must be kept before, during and after the performance.\\n\\n## Not allowed\\n- Fire, water or any hazardous props.\\n- Vulgarity, offensive gestures or inappropriate content.\\n- External devices on stage: only the submitted track or video is allowed.\\n\\n## Judging\\n- Choreography and creativity (Fusion theme) 40%, synchronization and coordination 25%, stage presence and expression 20%, costume, energy and overall impact 15%."}]`),r=[],s=[{Key:"SingingDate",Kind:"date",Label:"Aalaap (singing) date",Value:"2025-10-30",Source:"Aalaap"},{Key:"SingingTime",Kind:"time",Label:"Aalaap (singing) time",Value:"2:00 pm",Source:"Aalaap"},{Key:"InstrumentalDate",Kind:"date",Label:"SwarFusion (instrumental) date",Value:"2025-10-30",Source:"SwarFusion"},{Key:"InstrumentalTime",Kind:"time",Label:"SwarFusion (instrumental) time",Value:"3:30 pm",Source:"SwarFusion"},{Key:"SoloActDate",Kind:"date",Label:"Abhivyakti (solo act) date",Value:"2025-10-30",Source:"Abhivyakti"},{Key:"SoloActTime",Kind:"time",Label:"Abhivyakti (solo act) time",Value:"5:00 pm",Source:"Abhivyakti"},{Key:"StandUpDate",Kind:"date",Label:"Mic Drop (stand-up comedy) date",Value:"2025-10-31",Source:"Mic Drop"},{Key:"StandUpTime",Kind:"time",Label:"Mic Drop (stand-up comedy) time",Value:"5:00 pm",Source:"Mic Drop"},{Key:"DanceDate",Kind:"date",Label:"NrityaVerse (dance) date",Value:"2025-10-31",Source:"NrityaVerse"},{Key:"DanceTime",Kind:"time",Label:"NrityaVerse (dance) time",Value:"6:00 pm",Source:"NrityaVerse"},{Key:"MusicDeadline",Kind:"date",Label:"Deadline for music track and background video (singing and dance)",Value:"2025-10-28 9:00 AM",Source:"Aalaap 3, NrityaVerse 3"},{Key:"RegistrationCode",Kind:"text",Label:"How to register",Value:"The guidelines end with a 'Scan to Register' code; the registration link itself is not printed as text.",Source:"Last page"},{Key:"Prizes",Kind:"prize",Label:"Prizes",Value:"Cash prizes; the amounts are not printed and the number of prizes depends on the number of entries.",Source:"Prizes sections"}],l=[{Claim:"MIT-ADT University Quasar 2025 cultural competitions guidelines.",SourceType:"Primary - the event's own rules document",Source:"MIT-ADT University Quasar 2025, Guidelines and Rules for All Cultural Competitions",Url:"https://mitid.edu.in/quasar/pdf/cultural-competitions-30oct2025.pdf"}],c={TemplateKey:e,Year:2025,Note:n,Page:t,ParticipantTypes:i,AgeGroups:a,Competitions:o,CompetitionAgeGroups:r,Variables:s,Evidence:l};export{a as AgeGroups,r as CompetitionAgeGroups,o as Competitions,l as Evidence,n as Note,t as Page,i as ParticipantTypes,e as TemplateKey,s as Variables,d as Year,c as default};
